import storybook from 'eslint-plugin-storybook'
import { define } from 'rstack'
import fmt from 'rslint-config-cozy-app/fmt'
import react from 'rslint-config-cozy-app/react'

// Generated by the build:icons script of twake-icons
const generatedIcons = [
  'packages/twake-icons/src/Icons/**',
  'packages/twake-icons/src/Icon/icons-sprite.ts'
]

define.lint(lint => [
  {
    ignores: [
      ...generatedIcons,
      'packages/twake-icons/**/*.stories.{ts,tsx}',
      'packages/twake-mui/**/*.test.{ts,tsx}'
    ]
  },
  ...react(lint),
  // Rslint does not read the @(ts|tsx) globs of the storybook configs
  ...storybook.configs['flat/recommended'].map(config =>
    config.files
      ? {
          ...config,
          files: config.files.map(glob =>
            glob.replace(
              /@\(([^)]+)\)/g,
              (_, list) => `{${list.replaceAll('|', ',')}}`
            )
          )
        }
      : config
  )
])

define.fmt({
  ...fmt,
  ignorePatterns: [
    ...generatedIcons,
    // Written by semantic-release
    'CHANGELOG.md'
  ]
})
